def L(a,z):return '「'+''.join(T[a-1:z])+'」'
B=[
dict(a=1,z=2,star=2,lit=L(1,2),
key=[('亞捫','H5983','ammon','亞捫'),('後嗣','H3423','yoresh','後嗣、承受產業的人'),('瑪勒堪','H4428','malkam','瑪勒堪（他們的王）'),('拉巴','H7237','rabbat','拉巴（亞捫的首都）'),('喊聲','H8643','teruat','戰爭的喊聲'),('亂堆','H8510','tel','土堆、廢墟')],
gram=['**以色列沒有兒子嗎**：這是一個修辭問句，期待的回答是「有」。意思是：以色列有後嗣，產業不該被別人佔據。','**得以色列地為業**：同一個字根（承受產業）在二節再出現，先前佔據的，倒要被承受。'],
exp=['四十九章，是耶利米書論列國的第四篇，一口氣論了亞捫、以東、大馬士革、基達與夏瑣、以攔五處。一節先論亞捫人。亞捫，在約旦河東，和摩押一樣，是羅得的後代，與以色列有親戚的關係。','神的第一個問句很特別：以色列沒有兒子嗎？沒有後嗣嗎？瑪勒堪為何得迦得之地為業呢？意思是：迦得支派的地，本來是以色列的產業，亞捫的神（或亞捫的王，字面同為「瑪勒堪」）卻住在其中的城邑裡。這裡的重點，是「產業」被佔據這件事，經文沒有交代時間與經過，我們不替它補上歷史細節。','二節說：拉巴要成為亂堆，屬她的鄉村要被火焚燒；先前得以色列地為業的，此時以色列倒要得他們的地為業。請你留意，「得為業」這個字根，在這兩節裡反覆出現：佔據的，被反過來承受。這是一幅逆轉的畫面。我們不替這個預言加上日期，只看見：神記得祂百姓的產業。']),
dict(a=3,z=6,star=2,lit=L(3,6),
key=[('哀號','H3213','heylili','哀號'),('希實本','H2809','kheshbon','希實本'),('麻布','H8242','saqqim','麻布'),('背道','H7728','hashovevah','背道的、轉離的'),('倚靠','H982','habbetukhah','倚靠、信靠'),('歸回','H7725','ashiv','使歸回')],
gram=['**背道的民**：原文是「轉離的女兒」，「背道」與「歸回」同為 shuv 這個字根的家族，一個是轉離，一個是轉回。','**使被擄的歸回**：六節的動詞，主詞是神，意思是「我要使他們的境況翻轉過來」。'],
exp=['三節是一連串的命令：希實本哪，你要哀號；拉巴的居民哪，要呼喊，以麻布束腰；要哭號，在籬笆中跑來跑去。麻布束腰，是古代近東哀悼的記號。聖經沒有叫我們為亞捫的毀滅歡呼，它描寫的，是一座城市的哭聲。','四節，神問了一句：背道的民哪，你們為何因有山谷、就是水流的山谷誇張呢？為何倚靠財寶說：誰能來到我們這裡呢？這句話，和摩押的「倚靠自己的作為與財寶」是同一種心：覺得自己的地勢、自己的庫房，足以擋住一切。五節，神說：恐嚇要從四圍臨到你們，沒有人收聚逃民。','然而，六節的最後，是一句出人意料的話：後來我還要使被擄的亞捫人歸回。這是整個亞捫預言的結尾。審判在前面，盼望在末了。我們不替這句話加上日期，也不把它套用到今日任何地方，只看見：連論列國的信息，神也留下末了的一句。']),
dict(a=7,z=11,star=3,lit=L(7,11),
key=[('智慧','H2451','khokhmah','智慧'),('提幔','H8487','teiman','提幔（以東的一處）'),('以掃','H6215','esav','以掃'),('赤露','H2834','khasafti','使露出、使赤露'),('孤兒','H3490','yetomekha','孤兒'),('寡婦','H490','almenotekha','寡婦'),('倚靠','H982','yivtakhu','倚靠、信靠')],
gram=['**提幔**：以東地的地名，在聖經中常和智慧連在一起（參約伯記的提幔人以利法）。','**你撇下孤兒**：十一節的動詞是命令式的語氣，意思是：「你這些無人照顧的，交給我。」神自己站在孤兒寡婦這一邊。'],
exp=['七節，論以東。提幔中再沒有智慧嗎？明哲人不再有謀略嗎？他們的智慧盡歸無有嗎？以東，是以掃的後代，也是以色列最近的親戚之一。提幔，是以東的一處，以智慧著名。這是一個修辭問句，意思是：連最會謀算的人，也在神的審判之下。','八節勸底但的居民轉身逃跑，住在深密處；九節用兩個比喻：摘葡萄的來了，還剩下些葡萄；盜賊夜間來了，也只拿到夠用的。可是，十節說：我卻使以掃赤露，他不能自藏。意思是：這一次，連剩下的、連藏起來的，都無處可躲。','然後，在這一串沉重的話裡，突然出現十一節：你撇下孤兒，我必保全他們的命；你的寡婦可以倚靠我。請你留意：這句話，是在審判以東的篇章裡出現的。神一邊審判，一邊說：那些被留下的孤兒寡婦，我來保全。這是整章最溫柔的一節。我們不替這節加上任何政治的應用，只看見神的心：祂記得那些無人倚靠的人。','這一節也是新約的預備：詩篇說，神是孤兒的父、寡婦的伸冤者。耶利米書在這裡，用的是同一顆心。']),
dict(a=12,z=13,star=2,lit=L(12,13),
key=[('那杯','H3563','hakkos','那杯'),('免','H5352','naqoh','免去刑罰、無罪'),('起誓','H7650','nishbati','我起誓'),('波斯拉','H1224','botsrah','波斯拉（以東的城）'),('驚駭','H8047','leshammah','驚駭、荒涼'),('咒詛','H7045','liqelalah','咒詛')],
gram=['**原不該喝那杯的一定要喝**：「杯」在先知書中是審判的象徵（參耶二十五15--29）。','**我指著自己起誓**：神起誓的時候，是用祂自己的名，因為沒有比祂更大的可以指著起誓。'],
exp=['十二節，神說：原不該喝那杯的一定要喝，你能盡免刑罰嗎？你必不能免，一定要喝！這個「杯」，我們在耶利米書二十五章已經遇見過，是神憤怒的酒杯，要使列國輪流喝。意思是：連本來不該喝的，也要喝。這句話，讓我們看見審判的普遍。','十三節，神說：我指著自己起誓，波斯拉必令人驚駭、羞辱、咒詛，並且荒涼。神起誓，是用祂自己的名，因為沒有比祂更大的，可以指著起誓。這是一個很重的宣告。波斯拉，是以東的一座重要城市。','我們讀這兩節，要避免兩個誤用：不把這個杯，講成任何人可以拿來要求別人喝；也不把這個宣告，套用到今日任何地方。這一節是對那個時代、那座城市的宣告，我們只看見神的嚴肅。']),
dict(a=14,z=18,star=2,lit=L(14,18),
key=[('信息','H8052','shemuah','信息、消息'),('最小','H6996','qatan','最小、微小'),('藐視','H959','bazui','被藐視'),('狂傲','H2087','zadon','狂傲、自大'),('大鷹','H5404','nesher','大鷹'),('拉下','H3381','orideka','使下降、拉下'),('所多瑪','H5467','sedom','所多瑪')],
gram=['**心中的狂傲自欺**：原文是「你心中的狂傲，欺騙了你」，主詞是「狂傲」，受詞是「你」。驕傲，把人自己騙了。','**你雖如大鷹高高搭窩**：大鷹把窩築在高處，象徵以為自己安全。「我卻從那裡拉下你來」，是同一個高處的反轉。'],
exp=['十四節，神說：我從耶和華那裡聽見信息，並有使者被差往列國去，說：你們聚集來攻擊以東。十五節，神說：我使你在列國中為最小，在世人中被藐視。「為最小」，是和以東原來的自視相對的：他自以為是列國中最有智慧、最安全的。','十六節是這一段的中心：住在山穴中據守山頂的啊，論到你的威嚇，你因心中的狂傲自欺；你雖如大鷹高高搭窩，我卻從那裡拉下你來。請你留意，這節有一個有趣的次序：是你的狂傲，欺騙了你。我們以為，是別人的話或環境在騙我們；這一節說，最會欺騙我們的，是我們自己的心。','十七、十八節，描寫以東變成令人驚駭的地方，要像所多瑪、蛾摩拉傾覆的時候一樣。這些話很重，我們不替它們加上日期，也不把它們套用到今日任何地方、民族，更不拿它們去輕看任何人。我們只看見：驕傲，在聖經裡，是會自欺的。']),
dict(a=19,z=22,star=2,lit=L(19,22),
key=[('獅子','H738','aryeh','獅子'),('約旦河','H3383','hayarden','約旦河'),('牧人','H7462','roeh','牧人'),('謀略','H6098','atsat','謀略、計畫'),('震動','H7493','rashah','震動'),('紅海','H5488','suf','紅海（蘆葦海）'),('勇士','H1368','giborei','勇士')],
gram=['**誰能比我呢**：這是神的反問，不是在比高下，而是在宣告：沒有任何王、任何牧人，能站在神面前。','**謀略與旨意**：二十節的「謀略」和「定的旨意」是兩個動詞（yaats 與 khashav），都是「計畫」的意思，是神在審判裡的有意安排。'],
exp=['十九節，用獅子的比喻：仇敵必像獅子，從約旦河邊的叢林上來，攻擊堅固的居所。然後是一連串神的反問：誰能比我呢？誰能給我定規日期呢？有何牧人能在我面前站立得住呢？這幾句反問，讓我們看見：連列國的王，也是神所派的牧人，在祂面前站不住。','二十節，神說：你們要聽耶和華攻擊以東所說的謀略。這是一個很特別的邀請：神的計畫，不是黑箱，是可以「聽」的。二十一節，說他們仆倒的聲音，地就震動；人在紅海那裡必聽見呼喊的聲音。紅海，在以東的南邊；意思是：這聲音，傳得很遠。','二十二節，用大鷹飛起的畫面收尾：到那日，以東的勇士心中疼痛如臨產的婦人。這是一個很有力的比喻：最強壯的人，心中的疼痛，像生產的婦人。我們不替這節加上日期，只看見：在神面前，最強壯的人，也只是人。']),
dict(a=23,z=27,star=2,lit=L(23,27),
key=[('大馬士革','H1834','dammesek','大馬士革'),('蒙羞','H954','bushah','蒙羞'),('發軟','H7503','rafetah','發軟、鬆弛'),('痛苦','H6869','tsarah','痛苦、苦難'),('稱讚','H8416','tehillat','稱讚、榮耀'),('撇棄','H5800','uzzevah','被撇棄'),('宮殿','H759','armenot','宮殿')],
gram=['**我所喜樂可稱讚的城**：二十五節是一句哀歌式的問句。有人認為說話的是神，也有人認為是城中居民，經文沒有明說，我們不下定論。','**便‧哈達**：亞蘭王的名字（王下十三章），意思是「哈達（神）之子」。'],
exp=['二十三節，論大馬士革。哈馬和亞珥拔蒙羞，因他們聽見凶惡的信息就消化了。大馬士革，是亞蘭的首都，在以色列的東北方；哈馬和亞珥拔，是它附近的城市。「消化了」，是融化的意思，是心融化、勇氣融化的畫面。','二十四節，描寫大馬士革發軟，轉身逃跑，戰兢將她捉住；痛苦憂愁將她抓住，如產難的婦人一樣。這個比喻，和以東的勇士一樣，是用生產的疼痛，描寫失去力量。二十五節是一句很安靜的問句：我所喜樂可稱讚的城，為何被撇棄了呢？這句話，聽來像是一個人在為自己的故鄉哀嘆。經文沒有說明說話的是誰，我們不替它補上說話者。','二十六、二十七節，是審判的結尾：少年人必仆倒在街上，一切兵丁必默默無聲；我必在大馬士革城中使火著起，燒滅便‧哈達的宮殿。我們不替這節加上日期，也不套用到今日任何地方，只看見神的話，是對那個時代那座城的宣告。']),
dict(a=28,z=30,star=2,lit=L(28,30),
key=[('基達','H6938','qedar','基達（阿拉伯的遊牧部落）'),('夏瑣','H2674','khatsor','夏瑣（遊牧部落的營地）'),('尼布甲尼撒','H5019','nevukhadretstsar','尼布甲尼撒'),('帳棚','H168','ohaleihem','帳棚'),('駱駝','H1581','gemalleihem','駱駝'),('驚嚇','H4032','magor','驚嚇、恐怖'),('設計謀害','H3289','yaats','設計、謀劃')],
gram=['**基達與夏瑣**：基達，是遊牧的阿拉伯部落；夏瑣，是遊牧部落聚居的營地，不是以色列北方的夏瑣城。','**四圍都有驚嚇**：這個詞組（magor missavib）在耶利米書裡反覆出現，是一個標誌性的哀歌用語。'],
exp=['二十八節，論巴比倫王尼布甲尼撒所攻打的基達和夏瑣的諸國。基達，是東方的遊牧部落；夏瑣，是遊牧部落的營地。這一段是整章裡，第一次明確點出，審判的執行者，是巴比倫王尼布甲尼撒。','二十九節，描寫了這些遊牧人的財產：帳棚、羊群、幔子、器皿、駱駝，都要被奪去。人向他們喊著說：四圍都有驚嚇。這個詞組，我們在耶利米書的別處，已經聽過好幾次。三十節，神說：夏瑣的居民哪，要逃奔遠方，住在深密處；因為巴比倫王尼布甲尼撒設計謀害你們。','請你留意：神在這裡，是先給了一個警告：要逃，要住在深密處。這是神的憐憫：即使是在審判的宣告中，仍然有「逃」的路。我們不把這段套用到今日任何的遊牧民族，只看見：神的話，包括對一個不屬於以色列的、遙遠的人群。']),
dict(a=31,z=33,star=1,lit=L(31,33),
key=[('安逸','H7961','shalev','安逸、無憂'),('無閂','H1280','beriakh','門閂'),('獨自','H910','badad','獨自、孤立'),('掠物','H957','baz','掠物'),('剃周圍頭髮','H7112','qetsutsei','剃周圍頭髮的人'),('野狗','H8577','tannim','野狗、胡狼'),('淒涼','H8077','shemamah','淒涼、荒涼')],
gram=['**無門無閂、獨自居住**：這個描寫，在字面上是說，這群人沒有城牆和門，自覺安全，所以不設防。','**剃周圍頭髮的人**：這是古代某些阿拉伯部落的習俗（參耶九26），我們不在這裡描述更多細節。'],
exp=['三十一節，神說：迦勒底人哪，起來！上安逸無慮的居民那裡去；他們是無門無閂、獨自居住的。這裡的「安逸無慮」，和四十八章的摩押「自幼安逸」，是同一個字根。這一群人，不設防、不憂慮，自覺安全。','三十二、三十三節，宣告：他們的駱駝必成為掠物；他們眾多的牲畜必成為擄物。夏瑣必成為野狗的住處，永遠淒涼，必無人住在那裡，也無人在其中寄居。這些畫面，和對以東、對亞捫的描寫，大致相同。','我們可以從這一段，再一次看見：在耶利米書裡，審判的對象，包括一群沒有城牆、沒有軍隊、看起來最「安全」的人。真正的安全，不在於城門的閂有多堅固，而在於心裡倚靠的是誰。']),
dict(a=34,z=36,star=2,lit=L(34,36),
key=[('以攔','H5867','eylam','以攔'),('西底家','H6667','tsidqiyyahu','西底家'),('折斷','H7665','shover','折斷'),('弓','H7198','qeshet','弓'),('權力','H1369','gevuratam','權力、勇力'),('四風','H7307','ruchot','風、靈'),('分散','H2219','zeritim','使分散')],
gram=['**以攔**：在波斯灣以北的一個古國，在聖經裡常被描寫為善於射箭的民族（賽二十二6）。','**四風**：原文的「風」（ruakh）也是「靈」的字，這裡是氣象的風，意思是從四個方向來的風。'],
exp=['三十四節，是一個新的開頭：猶大王西底家登基的時候，耶和華論以攔的話臨到先知耶利米。這是整章裡，唯一明確標明時間記號的一個預言：西底家登基的時候。意思是：這是耶利米早期的話，在耶路撒冷陷落以前。','三十五節，神說：我必折斷以攔人的弓，就是他們為首的權力。以攔，以善射聞名；弓，是他們最大的力量。折斷弓，就是折斷他們最倚靠的東西。三十六節，神說：我要使四風從天的四方颳來，臨到以攔人，將他們分散四方。這被趕散的人沒有一國不到的。','請你留意：這是一個很獨特的預言，因為以攔，離以色列很遠，和耶利米的聽眾，沒有直接的親屬關係。神的話，連對最遠的人，也是這樣說的。我們不替這節加上日期，也不套用到今日的任何地方或民族。我們只看見：人最倚靠的力量，在神面前，是可以折斷的。']),
dict(a=37,z=39,star=3,lit=L(37,39),
key=[('驚惶','H2865','vehakhtati','使驚惶'),('烈怒','H2740','kharon','烈怒'),('刀劍','H2719','kherev','刀劍'),('寶座','H3678','kisi','我的寶座'),('除滅','H6','vehaavadti','除滅、使滅亡'),('末後','H319','beakharit','末後'),('歸回','H7725','ashiv','使歸回')],
gram=['**我要在以攔設立我的寶座**：這是一個宣告：連遠方的以攔，也在神的主權之下。','**到末後**：原文是「在日子的末後」，是先知書常見的詞組，指向一個沒有被說明日期的未來。'],
exp=['三十七節，神說：我必使以攔人在仇敵面前驚惶；我也必使災禍，就是我的烈怒臨到他們，又必使刀劍追殺他們，直到將他們滅盡。這是整章最重的一句審判之一。三十八節，神說：我要在以攔設立我的寶座，從那裡除滅君王和首領。意思是：神的審判，不只是對一個民族，也是對權力本身的宣告。','然後，是整章最後一節，三十九節：到末後，我還要使被擄的以攔人歸回。這句話，和六節對亞捫、和四十八章四十七節對摩押的話，是同一個句型。四十八章對摩押，四十九章對亞捫、對以攔，各有一句末了的應許；中間的以東、大馬士革、基達與夏瑣，則沒有。','我們不為這一句加上日期，也不推算誰是今日的以攔，也不把它套用到今日任何地方或民族。我們只看見：神是列國的主；祂的審判，是真實的，祂的應許，也是真實的。當我們讀完一整章，對我們每一個人，這個提醒是：我們不需要知道，誰得到應許、誰沒有；我們只需要把自己交給這位，在審判之中仍有末後的神。']),
]
